 "content": "from collections import deque


def transform(grid):
    """Fill background cells in any enclosed region with color 4."""
    h, w = len(grid), len(grid[0])
    background = min(v for row in grid for v in row)
    barriers = {v for row in grid for v in row if v != background}
    outside = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] not in barriers:
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] not in barriers and (nr, nc) not in outside:
                outside.add((nr, nc))
                q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in barriers and (r, c) not in outside:
                out[r][c] = 4
    return out


if __name__ == '__main__':
    # All three supplied examples contain enclosed background cavities.
    # Verify the painted cells while preserving their barrier boundaries.
    demo1 = [[5] * 21 for _ in range(13)]
    def line(g, r, a, b, color=1):
        for c in range(a, b + 1):
            g[r][c] = color
    line(demo1, 0, 5, 5)
    line(demo1, 1, 2, 6)
    line(demo1, 2, 0, 2); line(demo1, 2, 6, 20)
    line(demo1, 3, 2, 2); line(demo1, 3, 6, 20)
    line(demo1, 4, 2, 6)
    expected1 = [row[:] for row in demo1]
    for r in (2, 3):
        for c in (3, 4, 5):
            expected1[r][c] = 4
    assert transform(demo1) == expected1

    demo2 = [[8] * 27 for _ in range(10)]
    for r in (0, 1, 2, 7, 8, 9):
        demo2[r][6] = 9
    for r in (0, 1, 2):
        demo2[r][16] = 9
    for r in (3, 4, 5, 6):
        for c in range(3, 8): demo2[r][c] = 9
    for r in (3, 4, 5, 6):
        for c in range(15, 20): demo2[r][c] = 9
    for c in range(7, 16): demo2[4][c] = 9
    for c in range(3, 8): demo2[5][c] = 9
    expected2 = [row[:] for row in demo2]
    for r in (4, 5):
        for a, b in ((4, 6), (16, 18)):
            for c in range(a, b + 1): expected2[r][c] = 4
    assert transform(demo2) == expected2

    demo3 = [[5] * 13 for _ in range(10)]
    for c in range(6): demo3[4][c] = 1
    for c in range(6): demo3[5][c] = 1
    for c in range(13): demo3[5][c] = 1
    for c in range(6): demo3[6][c] = 1
    for r in range(7, 10): demo3[r][3] = 1
    expected3 = [row[:] for row in demo3]
    for c in range(1, 5): expected3[5][c] = 4
    assert transform(demo3) == expected3
    print('demonstrations verified')
    ",
